int X = 10, Y = 5, Z = 2;

// Default Precedence: Y * Z calculated first (10 + 10 = 20)
int val_default = X + Y * Z;

// Expression Grouping (Override Precedence)
// Ensures X + Y executes first (15 * 2 = 30)
int val_grouped = (X + Y) * Z;

// Readability: Grouping complex condition parts
bool status = true;
bool allow = (status && (X > Y)) || (Z == 2);

// Best Practice: Parenthesize macro arguments to prevent expansion issues
#define MULTIPLY(A, B) ((A) * (B))
int result = MULTIPLY(X + 1, Y); // Safe expansion
int bad_result = X + 1 * Y;      // Error prone (if not grouped)
